{%- set ts = state_attr('input_datetime.wasmachine_sessie_start', 'timestamp') -%}
{%- set elapsed = ((now().timestamp() - ts) / 60) if ts is not none else 0 -%}
{%- set durs = states('input_text.wasmachine_sessie_duren').split(',') | reject('in', ['', 'unknown','unavailable']) | map('float') | list -%}
{%- if durs | length == 0 -%}
90
{%- else -%}
{%- set cur_grof = states('input_text.wasmachine_huidige_curve_grof').split('|') | reject('in', ['', 'unknown','unavailable']) | map('float') | list -%}
{%- set curves_grof = states('input_text.wasmachine_sessie_curves_grof').split(';') | reject('in', ['', 'unknown','unavailable']) | list -%}
{%- set cur_fijn = states('input_text.wasmachine_huidige_curve').split('|') | reject('in', ['', 'unknown','unavailable']) | map('float') | list -%}
{%- set curves_fijn = states('input_text.wasmachine_sessie_curves').split(';') | reject('in', ['', 'unknown','unavailable']) | list -%}
{%- set curve_durs = states('input_text.wasmachine_curve_duren').split(',') | reject('in', ['', 'unknown','unavailable']) | map('float') | list -%}
{%- set n_fine = curves_fijn | length -%}
{%- set n_coarse = curves_grof | length -%}
{%- if n_fine == 0 or (cur_fijn | length == 0 and cur_grof | length == 0) -%}
{{ [((durs | sum / durs | length) - elapsed), 0] | max | round(0) }}
{%- else -%}
{%- set coarse_offset = n_fine - n_coarse -%}
{%- set aligned_durs = curve_durs -%}
{%- set ns = namespace(best_score=none, best_dur=aligned_durs[0], second_score=none, second_dur=none) -%}
{%- for i in range(n_fine) -%}
{%- set score = namespace(v=0, has_any=false) -%}
{%- if cur_fijn | length > 0 -%}
{%- set hist_fine = curves_fijn[i].split('|') | reject('in', ['', 'unknown','unavailable']) | map('float') | list -%}
{%- set nA = [cur_fijn|length, hist_fine|length] | min -%}
{%- if nA > 0 -%}
{%- set fd = namespace(v=0) -%}
{%- for j in range(nA) -%}{%- set fd.v = fd.v + (cur_fijn[j]-hist_fine[j])|abs -%}{%- endfor -%}
{%- set score.v = score.v + fd.v -%}
{%- set score.has_any = true -%}
{%- endif -%}
{%- endif -%}
{%- if cur_grof | length > 0 and i >= coarse_offset -%}
{%- set hist_coarse = curves_grof[i - coarse_offset].split('|') | reject('in', ['', 'unknown','unavailable']) | map('float') | list -%}
{%- set nB = [cur_grof|length, hist_coarse|length] | min -%}
{%- if nB > 0 -%}
{%- set cd = namespace(v=0) -%}
{%- for j in range(nB) -%}{%- set cd.v = cd.v + (cur_grof[j]-hist_coarse[j])|abs -%}{%- endfor -%}
{%- set score.v = score.v + cd.v -%}
{%- set score.has_any = true -%}
{%- endif -%}
{%- endif -%}
{%- if score.has_any -%}
{%- if ns.best_score is none or score.v < ns.best_score -%}
{%- set ns.second_score = ns.best_score -%}
{%- set ns.second_dur = ns.best_dur -%}
{%- set ns.best_score = score.v -%}
{%- set ns.best_dur = aligned_durs[i] -%}
{%- elif ns.second_score is none or score.v < ns.second_score -%}
{%- set ns.second_score = score.v -%}
{%- set ns.second_dur = aligned_durs[i] -%}
{%- endif -%}
{%- endif -%}
{%- endfor -%}
{%- if ns.second_dur is not none and elapsed > (ns.best_dur + 5) -%}
{{ [(ns.second_dur - elapsed), 0] | max | round(0) }}
{%- else -%}
{{ [(ns.best_dur - elapsed), 0] | max | round(0) }}
{%- endif -%}
{%- endif -%}
